            if (visible) {
                gridArea.style.display = 'block';
                percentArea.style.flex = '1 1 50%';
                gridArea.style.flex = '1 1 50%';
            } else {
                gridArea.style.display = 'none';
                percentArea.style.flex = '1 1 auto';
            }

